-- 人才与团队能力画像：研究专长、技术服务、导师关系、团队成员和项目分工。
BEGIN;

CREATE TABLE IF NOT EXISTS "人员科研能力" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "人员编号" integer NOT NULL,
    "研究专长" varchar(2000),
    "研究方向标签" varchar(1000),
    "技术服务能力" varchar(2000),
    "合作意愿" varchar(20) NOT NULL DEFAULT '可合作',
    "合作说明" varchar(1000),
    "可公开展示" boolean NOT NULL DEFAULT TRUE,
    "更新人编号" integer NOT NULL,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_人员科研能力" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_人员科研能力_人员" UNIQUE ("人员编号"),
    CONSTRAINT "ck_人员科研能力_合作意愿" CHECK ("合作意愿" IN ('可合作','需邀约','暂不合作'))
);

CREATE INDEX IF NOT EXISTS "ix_人员科研能力_合作意愿"
    ON "人员科研能力" ("合作意愿", "可公开展示");

CREATE TABLE IF NOT EXISTS "人员导师关系" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "导师编号" integer NOT NULL,
    "学员编号" integer NOT NULL,
    "关系类型" varchar(30) NOT NULL DEFAULT '科研导师',
    "开始日期" date,
    "结束日期" date,
    "状态" varchar(10) NOT NULL DEFAULT '有效',
    "备注" varchar(1000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_人员导师关系" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_人员导师关系_关系" UNIQUE ("导师编号", "学员编号", "关系类型"),
    CONSTRAINT "ck_人员导师关系_本人" CHECK ("导师编号" <> "学员编号"),
    CONSTRAINT "ck_人员导师关系_状态" CHECK ("状态" IN ('有效','结束','待确认')),
    CONSTRAINT "ck_人员导师关系_日期" CHECK ("结束日期" IS NULL OR "开始日期" IS NULL OR "结束日期" >= "开始日期")
);

CREATE INDEX IF NOT EXISTS "ix_人员导师关系_学员"
    ON "人员导师关系" ("学员编号", "状态");

CREATE TABLE IF NOT EXISTS "科研团队" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "团队名称" varchar(200) NOT NULL,
    "负责人编号" integer NOT NULL,
    "研究方向" varchar(2000),
    "技术服务范围" varchar(2000),
    "合作说明" varchar(1000),
    "状态" varchar(10) NOT NULL DEFAULT '筹建中',
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研团队" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研团队_名称" UNIQUE ("团队名称"),
    CONSTRAINT "ck_科研团队_状态" CHECK ("状态" IN ('筹建中','运行中','已解散'))
);

CREATE TABLE IF NOT EXISTS "科研团队成员" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "团队编号" bigint NOT NULL,
    "人员编号" integer NOT NULL,
    "成员角色" varchar(50) NOT NULL DEFAULT '成员',
    "加入日期" date,
    "退出日期" date,
    "状态" varchar(10) NOT NULL DEFAULT '有效',
    "备注" varchar(1000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研团队成员" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研团队成员_人员" UNIQUE ("团队编号", "人员编号"),
    CONSTRAINT "ck_科研团队成员_状态" CHECK ("状态" IN ('有效','退出','待确认')),
    CONSTRAINT "ck_科研团队成员_日期" CHECK ("退出日期" IS NULL OR "加入日期" IS NULL OR "退出日期" >= "加入日期")
);

CREATE INDEX IF NOT EXISTS "ix_科研团队成员_人员"
    ON "科研团队成员" ("人员编号", "状态");

CREATE TABLE IF NOT EXISTS "人员项目分工" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "流程模板编号" integer NOT NULL,
    "项目编号" integer NOT NULL,
    "人员编号" integer NOT NULL,
    "分工类型" varchar(50) NOT NULL,
    "工作量占比" numeric(5,2),
    "开始日期" date,
    "结束日期" date,
    "状态" varchar(10) NOT NULL DEFAULT '有效',
    "备注" varchar(1000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_人员项目分工" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_人员项目分工_人员" UNIQUE ("流程模板编号", "项目编号", "人员编号", "分工类型"),
    CONSTRAINT "ck_人员项目分工_工作量" CHECK ("工作量占比" IS NULL OR ("工作量占比" >= 0 AND "工作量占比" <= 100)),
    CONSTRAINT "ck_人员项目分工_状态" CHECK ("状态" IN ('有效','结束','待确认')),
    CONSTRAINT "ck_人员项目分工_日期" CHECK ("结束日期" IS NULL OR "开始日期" IS NULL OR "结束日期" >= "开始日期")
);

CREATE INDEX IF NOT EXISTS "ix_人员项目分工_项目"
    ON "人员项目分工" ("流程模板编号", "项目编号", "状态");
CREATE INDEX IF NOT EXISTS "ix_人员项目分工_人员"
    ON "人员项目分工" ("人员编号", "状态");

UPDATE "系统迁移版本"
   SET "版本" = 48,
       "脚本" = '001-048',
       "检查摘要" = '增加人员科研能力、团队、导师关系和项目分工画像'
 WHERE "编号" = 1;

COMMIT;
